const b = items[0].json.body || items[0].json;
const files = (b.files || []).filter(f => f && f.capturedAt).sort((a,z) => Date.parse(a.capturedAt) - Date.parse(z.capturedAt));
if (!files.length) throw new Error('Card manifest has no files with capturedAt');
const GAP = parseInt('{{CREA_SHOOT_GAP_MINUTES}}', 10) * 60 * 1000;
const shoots = [];
let cur = null;
for (const f of files) {
  const t = Date.parse(f.capturedAt);
  if (!cur || (t - cur.lastT) > GAP) { cur = { start: f.capturedAt, files: [], lastT: t }; shoots.push(cur); }
  cur.files.push(f); cur.lastT = t;
}
return shoots.map((s, i) => ({ json: {
  cardId: b.cardId || null,
  shootIndex: i + 1,
  shootCount: shoots.length,
  start: s.start,
  fileCount: s.files.length,
  files: s.files.map(f => f.name || f.path),
  folderName: '{{CREA_HIGGSFIELD_PROJECT_PREFIX}} ' + s.start.slice(0,10) + ' shoot ' + (i + 1)
} }));
